// FELEMAYE — Family & Loved Ones Design Survey (Framer code component). No login, no billing/contract/permit data.
// Route: publish on the page /survey/lorado (also works at /survey/lorado-family). The client slug is read from the URL, so every future client reuses this file.
// Backend: Supabase RPC submit_family_survey_v3 (security definer, rate-limited 60/hour, honeypot, whitelisted answer keys). Publishable key only.
// Layout: full desktop width, ONE vertical scroll (no inner scrollbars), arrow links jump section to section.
// Moodboard: the five original design-survey photos are built in. Add more in the sidebar (one per line: Label|image-url).
// @framerSupportedLayoutWidth any
// @framerSupportedLayoutHeight auto
import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

type Props = { supabaseUrl: string; publishableKey: string; projectSlug: string; title: string; address: string; moodImages: string; heading: string; intro: string; maxWidth: number; style?: React.CSSProperties }

const GOLD = "#D4A373", BG = "#0B0B0C", CARD = "#141416", LINE = "#222226", TEXT = "#EDE6D8", MUTED = "#A39B8B"
const SERIF = "'Cormorant Garamond',Georgia,serif", SANS = "Inter,system-ui,sans-serif", MONO = "ui-monospace,'SF Mono',Menlo,monospace"

const MOOD_IMG: Record<string, string> = {
 "Glass lanterns": "data:image/jpeg;base64,",
 "Sculpted sconces": "data:image/jpeg;base64,",
 "Jacaranda canopy": "data:image/jpeg;base64,",
 "Succulents": "data:image/jpeg;base64,",
 "Jasmine": "data:image/jpeg;base64,"
}
const MOOD_FALLBACK: [string, string[]][] = [["Warm plaster & clay", ["#C9A98A", "#A9714F", "#E8D8C2"]], ["Stone & water", ["#8E918C", "#3F4A4A", "#D5D8D0"]], ["Wood deck & cosy", ["#7A5233", "#C79B6A", "#EFE0C7"]]]
// Each moodboard card carries its group so lighting sits with lighting and plants with plants (one unified 4-column grid, no sub-stripes).
const MOOD_GROUP: Record<string, string> = { "Glass lanterns": "Lighting", "Sculpted sconces": "Lighting", "Jacaranda canopy": "Plants", "Succulents": "Plants", "Jasmine": "Plants", "Warm plaster & clay": "Materials", "Stone & water": "Materials", "Wood deck & cosy": "Materials" }
const RESIDENT = ["Yes, full-time", "No"]
const VISIT = ["Weekly", "Monthly", "Seasonal", "Holidays"]
// Complete design-intent item list from the master survey, grouped by category. Each item: Essential / Maybe / Pass.
const WISH: [string, string[]][] = [["Conversation & lounge", ["Conversation pit", "Sunken fire lounge", "Hammock", "Hanging egg or swing chair", "Bean bag & floor pouf lounge", "Moroccan floor seating", "Daybed", "Chaise lounges", "Built-in banquette", "Outdoor sectional", "Rocking chairs", "Window-seat nook"]], ["Dining & hosting", ["Large communal table", "Intimate bistro table", "Outdoor kitchen or grill", "Pizza oven", "Bar or serving ledge", "Beverage & wine cooler (age-appropriate)", "Dance or gathering floor", "Outdoor movie screen"]], ["Hearth & water", ["Fire pit or fireplace", "Water feature or fountain", "Reflecting pool", "Outdoor shower", "Hot tub or plunge pool", "Bird bath", "Rain chain"]], ["Wellness & ritual", ["Yoga or stretch space", "Meditation corner", "Sunrise coffee spot", "Cold plunge", "Sauna", "Reading nook", "Sunbathing deck"]], ["Family & play", ["Play or game area", "Bocce or lawn games", "Chalkboard wall", "Sensory garden", "Basketball hoop", "Pet-friendly turf"]], ["Garden & plants", ["Raised garden beds", "Herb wall", "Fruit trees", "Cutting garden", "Composting", "Living green wall", "Rain barrel"]], ["Lighting, sound & atmosphere", ["Outdoor speaker system", "Smart lighting control", "Statement lighting", "Shade structure (where zoning allows)", "Heaters or misters", "Ceiling fan", "Feature wall for art"]], ["Utility & threshold", ["Strong Wi-Fi coverage", "Charging outlets", "Camera & smart lock", "Package drop box", "Bike or scooter storage", "Hidden outdoor storage", "Screened trash & recycling", "Welcoming entry gate"]]]

const FEEL = ["Cozy", "Bright", "Calm", "Playful", "Fancy", "Wild & leafy", "Quiet corner", "Party-ready"]
const TIME = ["Early morning", "Midday", "Golden hour", "Evening", "Late night"]
const LIGHT = [["Warm lanterns", "soft glowing lanterns at night"], ["String lights", "twinkle lights overhead"], ["Bright sunshine", "lots of open sun"], ["Candle glow", "flickering and gentle"], ["Colour-changing", "lights that shift colour"]]
const LCTRL = ["Dimmable", "Path lights that switch on as you walk", "Fire or candle light", "Colour scenes", "Natural light only"]
const ACTS = ["Hosting dinners", "Quiet reading", "Kids and friends playing", "Gardening", "Working outside", "Movement or yoga", "Music and gatherings", "Pet space", "Outdoor cooking", "Stargazing", "Water sounds"]
const GROUP = ["Just me", "2 to 4 people", "5 to 10 people", "More than 10"]
const MATS = ["Warm wood", "Smooth plaster", "Rough stone", "Soft cushions & textiles", "Woven rattan", "Cool concrete", "Glazed tile", "Metal"]
const UNDER = ["Warm wood deck", "Gravel crunch", "Smooth stone", "Soft grass", "Patterned tile"]
const SEAT = ["Fire-pit circle", "Long family table", "Hammock", "Built-in benches", "Swing", "Big floor cushions", "Reading nook", "Steps to sit on"]
const SITLEN = ["Under 15 minutes", "About an hour", "1 to 2 hours", "All afternoon"]
const SHADE = ["Full sun", "Dappled shade", "Fully covered"]
const SEASON = ["Year-round", "Warm months", "Summer evenings only"]
const COMFORT = ["Fire pit", "Heaters", "Fans", "Misters", "Blankets"]
const PAL: [string, string[]][] = [["Terracotta & sand", ["#C46A4A", "#E7C9A5", "#8C5A3C"]], ["Olive & cream", ["#6B7340", "#F1E9D2", "#3D4426"]], ["Ocean & sage", ["#2F6B7C", "#A9C4B0", "#173F4C"]], ["Sunset & plum", ["#E08A4B", "#C65A7A", "#5A2D5E"]], ["Midnight & gold", ["#16213A", "#D4A373", "#0B0F1D"]], ["Rainbow tile", ["#E4572E", "#F3C13A", "#2E9CCA"]], ["Sage & dusty rose", ["#9AA58B", "#F1E8DD", "#C99A8E"]], ["Driftwood & deep teal", ["#B4A58E", "#EEEAE0", "#2F5D62"]]]

const slugFromUrl = (): string => { try { const m = window.location.pathname.match(/\/survey\/([^/]+?)(?:-family)?\/?$/i); return m ? decodeURIComponent(m[1]) : "" } catch { return "" } }

export default function FamilySurvey(props: Props) {
    const p = { supabaseUrl: "https://afejhlfwymwagstyfnse.supabase.co", publishableKey: "sb_publishable_DxxomxoBSa8QkC6pBzYf5A_O86rctbV", maxWidth: 896, projectSlug: "lorado", title: "The Lorado Courtyard", address: "3745 Lorado Way, View Park, CA", moodImages: "", heading: "The Courtyard, your way", intro: "The grown-ups are designing the courtyard, and your ideas count. There are no wrong answers. It takes about five minutes.", ...Object.fromEntries(Object.entries(props).filter(([, v]) => v !== undefined && v !== "")) } as Props
    const [nick, setNick] = React.useState(""); const [resident, setResident] = React.useState(""); const [visit, setVisit] = React.useState("")
    const [wl, setWl] = React.useState<Record<string, "E" | "M" | "P">>({})
    const [feel, setFeel] = React.useState<string[]>([]); const [light, setLight] = React.useState(""); const [seat, setSeat] = React.useState<string[]>([])
    const [pal, setPal] = React.useState(""); const [wish, setWish] = React.useState(""); const [mood, setMood] = React.useState<string[]>([])
    const [tod, setTod] = React.useState<string[]>([]); const [lctrl, setLctrl] = React.useState<string[]>([]); const [acts, setActs] = React.useState<string[]>([])
    const [group, setGroup] = React.useState(""); const [privacy, setPrivacy] = React.useState(0); const [flow, setFlow] = React.useState(0)
    const [mats, setMats] = React.useState<string[]>([]); const [under, setUnder] = React.useState(""); const [sitlen, setSitlen] = React.useState("")
    const [shade, setShade] = React.useState(""); const [season, setSeason] = React.useState(""); const [comfort, setComfort] = React.useState<string[]>([])
    const [hp, setHp] = React.useState("")
    const [state, setState] = React.useState<"idle" | "sending" | "done" | "error">("idle"); const [err, setErr] = React.useState("")
    const slug = slugFromUrl() || p.projectSlug
    const extraMood: [string, string][] = p.moodImages.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l, i) => { const [a, b] = l.includes("|") ? l.split("|") : [`Image ${i + 1}`, l]; return [a.trim(), b.trim()] as [string, string] })
    const moodItems: [string, string][] = [...Object.entries(MOOD_IMG), ...extraMood]
    const toggle = (list: string[], set: (v: string[]) => void, v: string, max: number) => set(list.includes(v) ? list.filter((x) => x !== v) : list.length >= max ? list : [...list, v])
    const filled = feel.length + seat.length + mood.length + tod.length + acts.length + mats.length + (light ? 1 : 0) + (pal ? 1 : 0) + (wish.trim() ? 1 : 0) + Object.keys(wl).length
    async function send() {
        if (!filled) { setErr("Pick at least one thing first."); return }
        setState("sending"); setErr("")
        const extra: Record<string, any> = { time_of_day: tod, light_control: lctrl, activities: acts, group_size: group, materials: mats, underfoot: under, sit_duration: sitlen, shade, seasons: season, comfort, resident, visit_freq: resident === "Yes, full-time" ? "" : visit }
        const wmap: Record<string, string> = { E: "wish_essential", M: "wish_maybe", P: "wish_pass" }
        Object.entries(wl).forEach(([item, v]) => { (extra[wmap[v]] = extra[wmap[v]] || []).push(item) })
        if (privacy) extra.privacy = String(privacy); if (flow) extra.flow = String(flow)
        try {
            const r = await fetch(`${p.supabaseUrl}/rest/v1/rpc/submit_family_survey_v3`, { method: "POST", headers: { "Content-Type": "application/json", apikey: p.publishableKey, Authorization: `Bearer ${p.publishableKey}` }, body: JSON.stringify({ p_slug: slug, p_nickname: nick, p_age_band: "", p_room_feel: feel, p_lighting: light, p_seating: seat, p_palette: pal, p_wish: wish, p_mood: mood, p_extra: extra, p_hp: hp }) })
            if (!r.ok) throw new Error(((await r.json().catch(() => ({}))) as any).message || "Something went wrong")
            setState("done"); try { window.scrollTo({ top: 0, behavior: "smooth" }) } catch {}
        } catch (e: any) { setState("error"); setErr(String(e.message || e).includes("too many") ? "Lots of people are answering right now. Please try again in a little while." : "That didn't go through. Please try again.") }
    }
    const chip = (on: boolean): React.CSSProperties => ({ font: `500 15px ${SANS}`, color: on ? "#0B0B0C" : TEXT, background: on ? GOLD : "transparent", border: `1px solid ${on ? GOLD : "#3a3a3c"}`, padding: "12px 16px", minHeight: 44, cursor: "pointer", textAlign: "left" })
    const chips = (items: string[], vals: string[], set: (v: string[]) => void, max: number) => <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>{items.map((f) => <button key={f} aria-pressed={vals.includes(f)} style={chip(vals.includes(f))} onClick={() => toggle(vals, set, f, max)}>{f}</button>)}</div>
    const radios = (items: string[], val: string, set: (v: string) => void, label: string) => <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }} role="radiogroup" aria-label={label}>{items.map((f) => <button key={f} role="radio" aria-checked={val === f} style={chip(val === f)} onClick={() => set(val === f ? "" : f)}>{f}</button>)}</div>
    const scale = (val: number, set: (n: number) => void, lo: string, hi: string) => (
        <div><div style={{ display: "grid", gridTemplateColumns: "repeat(5,1fr)", gap: 8 }}>{[1, 2, 3, 4, 5].map((n) => <button key={n} aria-pressed={val === n} style={{ ...chip(val === n), textAlign: "center" }} onClick={() => set(val === n ? 0 : n)}>{n}</button>)}</div>
            <div style={{ display: "flex", justifyContent: "space-between", font: `10px ${MONO}`, letterSpacing: ".14em", textTransform: "uppercase", color: MUTED, marginTop: 6 }}><span>{lo}</span><span>{hi}</span></div></div>
    )
    const sec = (id: string, n: string, t: string, sub: string, next: string | null, body: React.ReactNode) => (
        <section id={id} style={{ padding: "34px 0", borderTop: `1px solid ${LINE}`, scrollMarginTop: 16 }}>
            <div style={{ font: `10px ${MONO}`, letterSpacing: ".22em", textTransform: "uppercase", color: GOLD }}>{n}</div>
            <h2 style={{ font: `400 clamp(26px,3.6vw,38px)/1.12 ${SERIF}`, margin: "6px 0 4px", color: "#F2EBDD" }}>{t}</h2>
            <p style={{ margin: "0 0 16px", fontSize: 14, color: MUTED }}>{sub}</p>
            {body}
            {next && <a href={`#${next}`} onClick={(e) => { e.preventDefault(); try { document.getElementById(next)?.scrollIntoView({ behavior: "smooth", block: "start" }) } catch {} }} style={{ display: "inline-block", marginTop: 18, padding: "10px 0", font: `11px ${MONO}`, letterSpacing: ".2em", textTransform: "uppercase", color: GOLD, textDecoration: "none" }}>Next section ↓</a>}
        </section>
    )
    const css = `.fsv *{box-sizing:border-box}.fsv .two{display:grid;grid-template-columns:1fr 1fr;gap:28px}.fsv .moodgrid,.fsv .palgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.fsv .wlgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}@media (max-width:760px){.fsv .two{grid-template-columns:1fr}.fsv .moodgrid,.fsv .palgrid,.fsv .wlgrid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:380px){.fsv .moodgrid,.fsv .palgrid,.fsv .wlgrid{grid-template-columns:minmax(0,1fr)}}@media(max-width:760px){.fsv .two{grid-template-columns:1fr}.fsv .moodgrid,.fsv .palgrid,.fsv .wlgrid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:380px){.fsv .moodgrid,.fsv .palgrid,.fsv .wlgrid{grid-template-columns:minmax(0,1fr)}}.fsv button:focus-visible{outline:2px solid ${GOLD};outline-offset:2px}`
    return (
        <div className="fsv" style={{ ...props.style, position: "relative", background: BG, color: TEXT, fontFamily: SANS, width: "100%", boxSizing: "border-box", padding: "clamp(24px,5vw,64px) clamp(16px,4vw,56px) 96px", overflow: "hidden" }}>
            <style>{css}</style>
            <div className="max-w-4xl mx-auto" style={{ maxWidth: p.maxWidth || 896, margin: "0 auto" }}>
                <div style={{ font: `10px ${MONO}`, letterSpacing: ".28em", textTransform: "uppercase", color: MUTED }}>FELEMAYE | Studio Private Workspace · Family Design Survey</div>
                <h1 style={{ font: `400 clamp(38px,7vw,72px)/1.02 ${SERIF}`, margin: "14px 0 8px", color: "#F2EBDD" }}>{p.title}</h1>
                <div style={{ font: `11px ${MONO}`, letterSpacing: ".2em", textTransform: "uppercase", color: MUTED }}>{p.address}</div>
                <div style={{ borderBottom: `1px solid ${LINE}`, margin: "18px 0" }} />
                <h2 style={{ font: `400 clamp(22px,3.4vw,32px)/1.1 ${SERIF}`, letterSpacing: ".28em", textTransform: "uppercase", color: GOLD, margin: "0 0 12px" }}>BEFORE WE BEGIN</h2>
                {state !== "done" && <p style={{ fontSize: 17, lineHeight: 1.7, color: MUTED, maxWidth: 640, margin: 0 }}>{p.heading}. {p.intro}</p>}
                {state === "done" ? (
                    <div style={{ background: CARD, border: `1px solid ${LINE}`, padding: "32px 24px", marginTop: 32 }}>
                        <div style={{ font: `10px ${MONO}`, letterSpacing: ".22em", textTransform: "uppercase", color: GOLD }}>Received</div>
                        <h2 style={{ font: `400 34px/1.1 ${SERIF}`, margin: "10px 0" }}>Thank you{nick ? `, ${nick}` : ""}.</h2>
                        <p style={{ color: MUTED, lineHeight: 1.7, margin: 0 }}>Your ideas are in. The design team reads every one before the next design meeting. Anyone else in the family can answer too: just open the same link.</p>
                    </div>
                ) : (
                    <div style={{ marginTop: 28 }}>
                        {sec("s0", "00 · About you", "Who is answering?", "A first name or nickname is plenty. Please don't type last names, addresses or phone numbers anywhere.", "s1", (
                            <div>
                                <label style={{ display: "block", fontSize: 14, color: MUTED, maxWidth: 420 }}>First name or nickname (optional)
                                    <input value={nick} maxLength={30} onChange={(e) => setNick(e.target.value)} placeholder="Just a first name" style={{ display: "block", width: "100%", marginTop: 8, background: "transparent", border: 0, borderBottom: "1px solid #3a3a3c", color: TEXT, font: `17px ${SANS}`, padding: "10px 2px", outline: "none" }} />
                                </label>
                                <div className="two" style={{ marginTop: 22 }}>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Do you live here full-time?</div>{radios(RESIDENT, resident, setResident, "Lives here full-time")}</div>
                                    {resident === "No" && <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>If no, how often do you visit?</div>{radios(VISIT, visit, setVisit, "Visit frequency")}</div>}
                                </div>
                            </div>
                        ))}
                        {sec("s1", "01 · Moodboard", "Which of these feel right?", "Tap up to four. A first look before anything is drawn.", "s2", (
                            <div className="moodgrid">
                                {moodItems.map(([n, u]) => { const on = mood.includes(n); return (
                                    <button key={n} aria-pressed={on} aria-label={n} onClick={() => toggle(mood, setMood, n, 4)} style={{ ...chip(false), padding: 0, border: `1px solid ${on ? GOLD : "#3a3a3c"}`, boxShadow: on ? `0 0 0 1px ${GOLD}` : "none", overflow: "hidden" }}>
                                        <img src={u} alt={n} loading="lazy" style={{ display: "block", width: "100%", aspectRatio: "4 / 5", objectFit: "cover" }} />
                                        <div style={{ padding: "8px 10px", font: `500 13px ${SANS}`, color: TEXT }}><span style={{ display: "block", font: `9px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: GOLD, marginBottom: 2 }}>{MOOD_GROUP[n] || "Inspiration"}</span>{n}{on ? "  ✓" : ""}</div>
                                    </button>) })}
                                {MOOD_FALLBACK.map(([n, cols]) => { const on = mood.includes(n); return (
                                    <button key={n} aria-pressed={on} aria-label={n} onClick={() => toggle(mood, setMood, n, 4)} style={{ ...chip(false), padding: 0, border: `1px solid ${on ? GOLD : "#3a3a3c"}`, overflow: "hidden" }}>
                                        <div style={{ display: "flex", aspectRatio: "4 / 5" }}>{cols.map((c) => <div key={c} style={{ flex: 1, background: c }} />)}</div>
                                        <div style={{ padding: "8px 10px", font: `500 13px ${SANS}`, color: TEXT }}><span style={{ display: "block", font: `9px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: GOLD, marginBottom: 2 }}>{MOOD_GROUP[n] || "Materials"}</span>{n}{on ? "  ✓" : ""}</div>
                                    </button>) })}
                            </div>
                        ))}
                        {sec("s2", "02 · Feeling", "How should the courtyard feel?", "Pick up to three.", "s3", chips(FEEL, feel, setFeel, 3))}
                        {sec("s3", "03 · Light", "How should light behave?", "Think about when you will be out there and how you want it to glow.", "s4", (
                            <div className="two">
                                <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>When will you use it? (up to 3)</div>{chips(TIME, tod, setTod, 3)}</div>
                                <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Night-time mood (pick one)</div>
                                    <div style={{ display: "grid", gap: 8 }} role="radiogroup" aria-label="Lighting">{LIGHT.map(([n, d]) => <button key={n} role="radio" aria-checked={light === n} style={chip(light === n)} onClick={() => setLight(light === n ? "" : n)}><b>{n}</b><span style={{ opacity: 0.75 }}> · {d}</span></button>)}</div></div>
                                <div style={{ gridColumn: "1 / -1" }}><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>How should it be controlled? (up to 3)</div>{chips(LCTRL, lctrl, setLctrl, 3)}</div>
                            </div>
                        ))}
                        {sec("s4", "04 · Use", "What will happen out there?", "The things you would really do in the space. Pick up to four.", "s5", (
                            <div>
                                {chips(ACTS, acts, setActs, 4)}
                                <div className="two" style={{ marginTop: 24 }}>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Usual group size</div>{radios(GROUP, group, setGroup, "Group size")}</div>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Privacy</div>{scale(privacy, setPrivacy, "Open to the street", "Tucked away")}</div>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Indoor-outdoor flow</div>{scale(flow, setFlow, "Separate rooms", "One continuous space")}</div>
                                </div>
                            </div>
                        ))}
                        {sec("s5", "05 · Touch", "What should it feel like to touch?", "Materials and underfoot. Pick up to three.", "s6", (
                            <div className="two">
                                <div>{chips(MATS, mats, setMats, 3)}</div>
                                <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Underfoot</div>{radios(UNDER, under, setUnder, "Underfoot")}</div>
                            </div>
                        ))}
                        {sec("s6", "06 · Sitting", "Where and how would you sit?", "Seats, how long, and how comfortable you want to be.", "s7", (
                            <div>
                                {chips(SEAT, seat, setSeat, 3)}
                                <div className="two" style={{ marginTop: 24 }}>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Usually sitting for</div>{radios(SITLEN, sitlen, setSitlen, "Sitting time")}</div>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Sun or shade</div>{radios(SHADE, shade, setShade, "Shade")}</div>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Which seasons</div>{radios(SEASON, season, setSeason, "Seasons")}</div>
                                    <div><div style={{ font: `10px ${MONO}`, letterSpacing: ".18em", textTransform: "uppercase", color: MUTED, marginBottom: 10 }}>Staying comfortable (up to 3)</div>{chips(COMFORT, comfort, setComfort, 3)}</div>
                                </div>
                            </div>
                        ))}
                        {sec("s7", "07 · Colour", "Which colours feel like home?", "Pick your favourite set. Eight to choose from.", "s8", (
                            <div className="palgrid" role="radiogroup" aria-label="Colour palette">
                                {PAL.map(([n, cols]) => (
                                    <button key={n} role="radio" aria-checked={pal === n} onClick={() => setPal(pal === n ? "" : n)} style={{ ...chip(false), padding: 0, border: `1px solid ${pal === n ? GOLD : "#3a3a3c"}`, boxShadow: pal === n ? `0 0 0 1px ${GOLD}` : "none" }}>
                                        <div style={{ display: "flex", height: 54 }}>{cols.map((c) => <div key={c} style={{ flex: 1, background: c }} />)}</div>
                                        <div style={{ padding: "10px 12px", font: `500 14px ${SANS}`, color: TEXT }}>{n}{pal === n ? "  ✓" : ""}</div>
                                    </button>
                                ))}
                            </div>
                        ))}
                        {sec("s8", "08 · Wishlist", "Essential, maybe, or pass?", "Mark each idea. Skip anything you have no opinion on.", "s9", (
                            <div>
                                {WISH.map(([cat, items]) => (
                                    <div key={cat} style={{ marginBottom: 28 }}>
                                        <div style={{ font: `10px ${MONO}`, letterSpacing: ".2em", textTransform: "uppercase", color: GOLD, margin: "0 0 12px" }}>{cat}</div>
                                        <div className="wlgrid">
                                            {items.map((it) => (
                                                <div key={it} style={{ border: `1px solid ${wl[it] ? GOLD : "#2a2a2d"}`, background: CARD, padding: 10, display: "flex", flexDirection: "column", justifyContent: "space-between", gap: 10, minWidth: 0 }}>
                                                    <div style={{ font: `500 14px/1.3 ${SANS}`, overflowWrap: "anywhere" }}>{it}</div>
                                                    <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 4 }} role="radiogroup" aria-label={it}>
                                                        {([["E", "Essential"], ["M", "Maybe"], ["P", "Pass"]] as const).map(([k, l]) => <button key={k} role="radio" aria-checked={wl[it] === k} onClick={() => setWl((o) => { const n = { ...o }; if (n[it] === k) delete n[it]; else n[it] = k; return n })} style={{ font: `600 9px ${MONO}`, letterSpacing: ".06em", textTransform: "uppercase", minHeight: 36, padding: "0 2px", cursor: "pointer", color: wl[it] === k ? "#0B0B0C" : MUTED, background: wl[it] === k ? (k === "P" ? "#8a8578" : GOLD) : "transparent", border: `1px solid ${wl[it] === k ? "transparent" : "#3a3a3c"}` }}>{l}</button>)}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ))}
                        {sec("s9", "09 · One wish", "If anything were possible…", "What do you wish the courtyard had?", null, (
                            <div>
                                <textarea value={wish} maxLength={400} onChange={(e) => setWish(e.target.value)} rows={4} placeholder="A tree house? A tiny stage? A place for a pet? Tell us." style={{ width: "100%", background: "transparent", color: TEXT, border: "1px solid #3a3a3c", padding: 14, font: `16px/1.6 ${SANS}`, outline: "none", resize: "vertical" }} />
                                <div style={{ textAlign: "right", fontSize: 12, color: MUTED }}>{wish.length}/400</div>
                                <input tabIndex={-1} autoComplete="off" aria-hidden="true" value={hp} onChange={(e) => setHp(e.target.value)} style={{ position: "absolute", left: "-9999px", width: 1, height: 1, opacity: 0 }} />
                                {err && <p role="alert" style={{ color: "#E08A7A", fontSize: 14 }}>{err}</p>}
                                <button onClick={send} disabled={state === "sending"} style={{ marginTop: 18, width: "100%", maxWidth: 420, minHeight: 54, background: GOLD, color: "#0B0B0C", border: 0, font: `600 12px ${MONO}`, letterSpacing: ".22em", textTransform: "uppercase", cursor: "pointer" }}>{state === "sending" ? "Sending…" : "Send my ideas"}</button>
                                <p style={{ fontSize: 12, color: MUTED, margin: "12px 0 0" }}>This survey shows no billing, contract or permit information. Answers go only to the design team and the homeowner.</p>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    )
}
